#!/usr/bin/env python3
"""Render the general chapters' geometry figures from real FerroCAD geometry.

The concept diagrams under ``docs/general/images/`` are two kinds of asset:

* hand-authored SVGs, generated by ``tools/generate_concept_diagrams.py``;
* viewport snapshots, generated here. These are rendered by
  ``ferrocad_snapshot`` — the same offscreen renderer the documentation
  screenshots use — from a spec built out of the real ``Part`` and ``Mesh``
  modules, so the picture cannot describe geometry the code does not produce.

``docs/general/images/manifest.json`` pins each PNG to the spec that produced it
and to the byte digest. ``--check`` is GPU-free: it verifies the manifest, the
committed PNG and that the generator itself has not changed since the capture.
When the ``Part`` module is importable it also rebuilds each spec and compares
the digest; without a kernel it says so and checks the rest.

Usage::

    LD_LIBRARY_PATH=.occt/prefix/lib PYTHONPATH=python \\
        python3 tools/generate_general_figures.py --capture
    python3 tools/generate_general_figures.py --check
    python3 tools/generate_general_figures.py --list
"""

from __future__ import annotations

import argparse
import hashlib
import json
import math
import os
import subprocess
import sys
from dataclasses import dataclass
from pathlib import Path
from typing import Callable

TOOLS = Path(__file__).resolve().parent
REPO = TOOLS.parent
sys.path.insert(0, str(TOOLS))

import userdocs  # noqa: E402

OUT = REPO / "docs" / "general" / "images"
MANIFEST = OUT / "manifest.json"
MANIFEST_VERSION = 1

#: Positions come from a floating-point kernel; six decimals keep the spec digest
#: stable across processes without changing what is drawn.
PRECISION = 6


def _round(value: float) -> float:
    rounded = round(float(value), PRECISION)
    return 0.0 if rounded == 0.0 else rounded


def _quantize(value):
    """Round every float in a nested list/``dict`` structure."""
    if isinstance(value, float):
        return _round(value)
    if isinstance(value, dict):
        return {key: _quantize(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [_quantize(item) for item in value]
    return value


def _flat_edges(facets) -> list[int]:
    """The unique edges of a triangle list, as a flat ``(a, b)`` index array."""
    pairs = {
        (min(a, b), max(a, b))
        for triangle in facets
        for a, b in (
            (triangle[0], triangle[1]),
            (triangle[1], triangle[2]),
            (triangle[2], triangle[0]),
        )
    }
    return [index for pair in sorted(pairs) for index in pair]


# ---------------------------------------------------------------------------
# Figure builders
# ---------------------------------------------------------------------------


def sphere_mesh_vs_brep() -> dict:
    """One radius-10 sphere, once stored as a mesh and once kept as B-Rep.

    Both halves come from the same ``Part.makeSphere(10)``; only the tessellation
    settings differ. The left half is tessellated coarsely (80 triangles) and kept
    in a real ``Mesh.Mesh`` — that is the representation a mesh file stores. The
    right half stays a B-Rep shape and is meshed finely for the viewport only,
    with smooth normals and the shape's own edge polylines.
    """
    import Mesh
    import Part

    shape = Part.makeSphere(10.0)

    # Left: the coarse tessellation, stored as a mesh. `Mesh.Mesh` accepts the
    # (points, facets) tuple directly, which is exactly upstream's API. Ask for the
    # coarse mesh before the fine one below: OCCT stores the triangulation on the
    # shape and only re-meshes when the request is finer, so the reverse order
    # would make the mesh half silently fine.
    coarse = Mesh.Mesh(shape.tessellate(2.0, 1.0))
    points, facets = coarse.Topology
    mesh_positions = [[point.x - 15.0, point.y, point.z] for point in points]
    mesh_triangles = [index for facet in facets for index in facet]

    # Right: the display mesh the viewport gets. Its positions cover faces, edges
    # and vertices; for a sphere every one of them has the same normal, p / r.
    display = shape.mesh(0.2, 0.2)
    # Turn the seam meridian away from the silhouette so it is visible. A sphere is
    # rotationally symmetric, so this changes the picture, not the geometry.
    angle = math.radians(-80.0)
    cos, sin = math.cos(angle), math.sin(angle)

    def turn(position: list[float]) -> list[float]:
        x, y = position[0], position[1]
        return [x * cos - y * sin, x * sin + y * cos, position[2]]

    brep_positions = []
    brep_normals = []
    for x, y, z in display["positions"]:
        rx, ry, rz = turn([x, y, z])
        brep_positions.append([rx + 15.0, ry, rz])
        brep_normals.append(turn([x / 10.0, y / 10.0, z / 10.0]))

    spec = {
        "size": [960, 420],
        "camera": {"eye": [0.0, -58.0, 18.0], "target": [0.0, 0.0, 0.0], "fov_y": 0.62},
        "shapes": [
            {
                "geometry": {
                    "mesh": {
                        "positions": mesh_positions,
                        "triangles": mesh_triangles,
                        "edges": _flat_edges(facets),
                    }
                },
                "color": [0.78, 0.78, 0.78, 1.0],
                "edge_color": [0.30, 0.30, 0.30, 1.0],
                "draw_mode": "shaded_edges",
            },
            {
                "geometry": {
                    "mesh": {
                        "positions": brep_positions,
                        "normals": brep_normals,
                        "triangles": display["triangles"],
                        "edges": display["edges"],
                    }
                },
                "color": [0.42, 0.62, 0.88, 1.0],
                "edge_color": [0.10, 0.30, 0.65, 1.0],
                "draw_mode": "shaded_edges",
            },
        ],
    }
    return _quantize(spec)


@dataclass(frozen=True)
class Figure:
    name: str
    description: str
    build: Callable[[], dict]


FIGURES = (
    Figure(
        "sphere-mesh-vs-brep.png",
        "A sphere stored as an 80-triangle mesh, next to the same sphere kept as B-Rep.",
        sphere_mesh_vs_brep,
    ),
)


# ---------------------------------------------------------------------------
# Manifest
# ---------------------------------------------------------------------------


def _generator_digest() -> str:
    """The generator's own digest, with line endings normalised.

    A recorded digest means an edit to this file makes the manifest stale, so
    ``--check`` catches a changed figure even where the kernel is unavailable.
    """
    text = Path(__file__).read_text(encoding="utf-8").replace("\r\n", "\n")
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def _spec_digest(spec: dict) -> str:
    return userdocs.spec_digest(spec)


def _png_digest(data: bytes) -> str:
    return userdocs.png_digest(data)


def build_manifest(pngs: dict[str, bytes], specs: dict[str, dict]) -> dict:
    entries = {}
    for name in sorted(specs):
        data = pngs[name]
        spec = specs[name]
        entries[name] = {
            "figure": Path(name).stem,
            "spec_sha256": _spec_digest(spec),
            "size": [int(value) for value in spec.get("size", userdocs.SNAPSHOT_DEFAULT_SIZE)],
            "png_sha256": _png_digest(data),
            "bytes": len(data),
        }
    return {
        "version": MANIFEST_VERSION,
        "generator": "tools/generate_general_figures.py",
        "generator_sha256": _generator_digest(),
        "images": entries,
    }


def load_manifest() -> dict | None:
    if not MANIFEST.is_file():
        return None
    try:
        data = json.loads(MANIFEST.read_text())
    except json.JSONDecodeError as exc:
        raise RuntimeError(f"{MANIFEST.relative_to(REPO)} is not valid JSON: {exc}") from exc
    if data.get("version") != MANIFEST_VERSION:
        raise RuntimeError(
            f"{MANIFEST.relative_to(REPO)} has version {data.get('version')!r}; "
            f"expected {MANIFEST_VERSION}"
        )
    if not isinstance(data.get("images"), dict):
        raise RuntimeError(f"{MANIFEST.relative_to(REPO)} has no images object")
    return data


def write_manifest(manifest: dict) -> None:
    text = json.dumps(manifest, indent=2, sort_keys=True) + "\n"
    temporary = MANIFEST.with_name(f".{MANIFEST.name}.tmp")
    temporary.write_text(text)
    os.replace(temporary, MANIFEST)


# ---------------------------------------------------------------------------
# Commands
# ---------------------------------------------------------------------------


def capture() -> int:
    """Build every spec, render it, and write the PNGs and manifest."""
    try:
        specs = {figure.name: figure.build() for figure in FIGURES}
    except ImportError as exc:
        print(
            "error: the Part module is not importable; run with "
            "LD_LIBRARY_PATH=.occt/prefix/lib PYTHONPATH=python",
            file=sys.stderr,
        )
        print(f"       {exc}", file=sys.stderr)
        return 2

    binary = userdocs.snapshot_binary()
    staging = REPO / "target" / "general-figures"
    staging.mkdir(parents=True, exist_ok=True)

    pngs: dict[str, bytes] = {}
    for name, spec in specs.items():
        spec_path = staging / f"{Path(name).stem}.json"
        png_path = staging / name
        spec_path.write_text(json.dumps(spec, sort_keys=True))
        result = subprocess.run(
            [str(binary), str(spec_path), str(png_path)],
            capture_output=True,
            text=True,
            check=False,
        )
        if result.returncode == userdocs.SNAPSHOT_NO_ADAPTER:
            print(
                "no GPU adapter available; leaving the committed images unchanged",
                file=sys.stderr,
            )
            return 3
        if result.returncode != 0:
            print(result.stderr.strip() or result.stdout.strip(), file=sys.stderr)
            return 2
        pngs[name] = png_path.read_bytes()
        if not (OUT / name).is_file() or (OUT / name).read_bytes() != pngs[name]:
            (OUT / name).write_bytes(pngs[name])
            print(f"wrote docs/general/images/{name}")
        else:
            print(f"unchanged docs/general/images/{name}")

    write_manifest(build_manifest(pngs, specs))
    print("wrote docs/general/images/manifest.json")
    return 0


def check() -> int:
    """Verify the manifest, the PNGs, and (when possible) the specs."""
    errors: list[str] = []
    manifest = load_manifest()
    if manifest is None:
        print(
            "missing docs/general/images/manifest.json "
            "(run `python3 tools/generate_general_figures.py --capture`)",
            file=sys.stderr,
        )
        return 1

    if manifest.get("generator_sha256") != _generator_digest():
        errors.append(
            "stale generator: tools/generate_general_figures.py changed since the "
            "capture (run `--capture`)"
        )

    entries = manifest["images"]
    expected = {figure.name for figure in FIGURES}

    for name in sorted(expected):
        entry = entries.get(name)
        if entry is None:
            errors.append(f"missing manifest entry: {name} (run `--capture`)")
            continue
        target = OUT / name
        if not target.is_file():
            errors.append(f"missing image: {name} (run `--capture`)")
            continue
        data = target.read_bytes()
        if entry.get("png_sha256") != _png_digest(data):
            errors.append(f"stale image: {name} (run `--capture`)")
        if entry.get("bytes") != len(data):
            errors.append(f"stale byte count: {name} (run `--capture`)")

    for name in sorted(set(entries) - expected):
        errors.append(f"orphan manifest entry: {name} (no figure produces it)")

    try:
        import Part  # noqa: F401
    except ImportError:
        print(
            "note: Part is not importable, so the render specs were not rebuilt; "
            "the manifest, PNG digests and generator digest were checked."
        )
    else:
        for figure in FIGURES:
            entry = entries.get(figure.name)
            if entry is None:
                continue
            digest = _spec_digest(figure.build())
            if entry.get("spec_sha256") != digest:
                errors.append(
                    f"stale spec: {figure.name} (the produced geometry changed; "
                    "run `--capture`)"
                )

    for error in errors:
        print(f"error: {error}", file=sys.stderr)
    if errors:
        return 1
    print("general figures are current")
    return 0


def list_figures() -> int:
    for figure in FIGURES:
        print(f"{figure.name}\n  {figure.description}")
    return 0


def main(argv: list[str]) -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    group = parser.add_mutually_exclusive_group(required=True)
    group.add_argument("--capture", action="store_true", help="render the PNGs and rewrite the manifest")
    group.add_argument("--check", action="store_true", help="verify the manifest and committed PNGs")
    group.add_argument("--list", action="store_true", help="list the figures")
    args = parser.parse_args(argv)

    if args.capture:
        return capture()
    if args.check:
        return check()
    return list_figures()


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
